-- Food safety department: versioned requirements, private education media and attestations.
CREATE SCHEMA hvm_food_private;
REVOKE ALL ON SCHEMA hvm_food_private FROM PUBLIC;
GRANT USAGE ON SCHEMA hvm_food_private TO service_role,anon,authenticated;
CREATE TABLE public.app_food_configuration(id boolean PRIMARY KEY DEFAULT true CHECK(id),enabled boolean NOT NULL DEFAULT false);
INSERT INTO public.app_food_configuration(id,enabled) VALUES(true,false);
CREATE TABLE public.app_food_rules(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,
 draft_body jsonb NOT NULL CHECK(jsonb_typeof(draft_body)='object'),
 status text NOT NULL CHECK(status IN ('draft','published','archived')),
 revision integer NOT NULL DEFAULT 1 CHECK(revision>0),current_version_id uuid,
 is_core boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.app_food_rule_versions(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),rule_id uuid NOT NULL REFERENCES public.app_food_rules(id),
 version integer NOT NULL CHECK(version>0),body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'),
 created_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 UNIQUE(rule_id,version),UNIQUE(rule_id,id)
);
ALTER TABLE public.app_food_rules ADD CONSTRAINT fk_food_current_version FOREIGN KEY(id,current_version_id)
 REFERENCES public.app_food_rule_versions(rule_id,id) DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE public.app_food_assets(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),object_path text UNIQUE NOT NULL,
 mime_type text NOT NULL CHECK(mime_type IN ('image/jpeg','image/png','image/webp','video/mp4','video/webm')),
 bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 33554432),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready')),
 uploaded_by uuid REFERENCES public.app_users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE TABLE public.app_food_materials(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),body jsonb NOT NULL CHECK(jsonb_typeof(body)='object'),
 status text NOT NULL CHECK(status IN ('draft','published','archived')),revision integer NOT NULL DEFAULT 1 CHECK(revision>0),
 updated_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
ALTER TABLE public.app_products
 ADD COLUMN food_family text CHECK(food_family IN ('fruits','leafy','vegetables','mixes','herbs','juices_pulps','grains','nuts','animal','other')),
 ADD COLUMN food_process text CHECK(food_process IN ('fresh','washed_cut','frozen','dried','pressed_pulped','prepared')),
 ADD COLUMN food_revision integer NOT NULL DEFAULT 1 CHECK(food_revision>0),
 ADD COLUMN food_hold boolean NOT NULL DEFAULT false,
 ADD COLUMN food_hold_reason text;
CREATE TABLE public.app_food_acceptances(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_id uuid REFERENCES public.app_products(id) ON DELETE SET NULL,
 actor_id uuid REFERENCES public.app_users(id) ON DELETE SET NULL,product_title text NOT NULL,
 food_revision integer NOT NULL CHECK(food_revision>0),rule_version_ids uuid[] NOT NULL CHECK(cardinality(rule_version_ids)>0),
 location_state text NOT NULL,location_municipality text NOT NULL,
 requirements_token text NOT NULL CHECK(requirements_token~'^[a-f0-9]{64}$'),
 checked_keys text[] NOT NULL,rule_snapshot jsonb NOT NULL,terms_snapshot jsonb NOT NULL,
 accepted_at timestamptz NOT NULL DEFAULT clock_timestamp(),client_ip_hash text,
 command_id uuid NOT NULL UNIQUE
);
CREATE INDEX ix_food_acceptance_product ON public.app_food_acceptances(product_id,food_revision,accepted_at DESC);
CREATE INDEX ix_food_rules_current ON public.app_food_rules(current_version_id) WHERE status<>'archived';
CREATE INDEX ix_food_version_scope ON public.app_food_rule_versions((body->>'scope'),(body->>'state'));
CREATE INDEX ix_food_material_published ON public.app_food_materials(updated_at DESC) WHERE status='published';
CREATE INDEX ix_food_rule_creator ON public.app_food_rule_versions(created_by) WHERE created_by IS NOT NULL;
CREATE INDEX ix_food_asset_creator ON public.app_food_assets(uploaded_by) WHERE uploaded_by IS NOT NULL;
CREATE INDEX ix_food_acceptance_actor ON public.app_food_acceptances(actor_id) WHERE actor_id IS NOT NULL;
ALTER TABLE public.app_food_configuration ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_food_rules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_food_rule_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_food_assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_food_materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_food_acceptances ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.app_food_configuration,public.app_food_rules,public.app_food_rule_versions,public.app_food_assets,public.app_food_materials,public.app_food_acceptances FROM PUBLIC,anon,authenticated;
GRANT SELECT,UPDATE ON public.app_food_configuration TO service_role;
GRANT SELECT,INSERT,UPDATE ON public.app_food_rules,public.app_food_assets,public.app_food_materials TO service_role;
GRANT SELECT,INSERT ON public.app_food_rule_versions,public.app_food_acceptances TO service_role;
CREATE FUNCTION hvm_food_private.expected_versions(product uuid) RETURNS uuid[] LANGUAGE sql STABLE SECURITY INVOKER SET search_path='' AS $$
 SELECT coalesce(array_agg(v.id ORDER BY v.id),'{}'::uuid[])
 FROM public.app_products p JOIN public.app_producer_stores s ON s.id=p.store_id
 JOIN public.app_properties loc ON loc.id=s.property_id
 JOIN public.app_food_rules r ON r.current_version_id IS NOT NULL AND r.status<>'archived'
 JOIN public.app_food_rule_versions v ON v.id=r.current_version_id
 WHERE p.id=product
 AND (CASE WHEN v.body->>'matchMode'='any' THEN
   (jsonb_array_length(v.body->'families')=0 AND jsonb_array_length(v.body->'processes')=0) OR
   (v.body->'families') ? p.food_family OR (v.body->'processes') ? p.food_process
 ELSE (jsonb_array_length(v.body->'families')=0 OR (v.body->'families') ? p.food_family)
  AND (jsonb_array_length(v.body->'processes')=0 OR (v.body->'processes') ? p.food_process) END)
 AND (jsonb_array_length(v.body->'categoryIds')=0 OR (v.body->'categoryIds') ? p.category_id::text)
 AND (v.body->>'scope'='national' OR v.body->>'state'=loc.state)
 AND (v.body->>'scope'<>'municipality' OR public.fn_locality_normalize(v.body->>'municipality')=public.fn_locality_normalize(loc.municipality))
$$;
-- The only anonymous capability is this boolean availability lookup. It exposes
-- no attestation, identity, draft rule, asset, or private location data.
CREATE FUNCTION hvm_food_private.product_is_compliant(product uuid) RETURNS boolean
 LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT CASE WHEN NOT (SELECT enabled FROM public.app_food_configuration WHERE id) THEN true ELSE
 EXISTS(SELECT 1 FROM public.app_products p WHERE p.id=product AND NOT p.food_hold
 AND p.food_family IS NOT NULL AND p.food_process IS NOT NULL
 AND cardinality(hvm_food_private.expected_versions(p.id))>0
 AND (current_setting('role',true) NOT IN ('anon','authenticated') OR (p.is_published AND hvm_store_private.store_is_visible(p.store_id)
   AND EXISTS(SELECT 1 FROM public.app_categories cat WHERE cat.id=p.category_id AND cat.is_active)))
 AND EXISTS(SELECT 1 FROM public.app_food_acceptances a JOIN public.app_producer_stores s ON s.id=p.store_id
  JOIN public.app_properties loc ON loc.id=s.property_id
  WHERE a.product_id=p.id AND a.food_revision=p.food_revision AND a.location_state=loc.state
  AND public.fn_locality_normalize(a.location_municipality)=public.fn_locality_normalize(loc.municipality)
  AND a.rule_version_ids @> hvm_food_private.expected_versions(p.id))) END
$$;
CREATE FUNCTION hvm_food_private.food_revision() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF ROW(NEW.category_id,NEW.title,NEW.description,NEW.packaging_type,NEW.net_weight_grams,NEW.unit_type,NEW.shelf_life_days,NEW.conservation_notes,NEW.food_family,NEW.food_process)
 IS DISTINCT FROM ROW(OLD.category_id,OLD.title,OLD.description,OLD.packaging_type,OLD.net_weight_grams,OLD.unit_type,OLD.shelf_life_days,OLD.conservation_notes,OLD.food_family,OLD.food_process)
 THEN NEW.food_revision:=OLD.food_revision+1; ELSE NEW.food_revision:=OLD.food_revision; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_food_revision BEFORE UPDATE ON public.app_products FOR EACH ROW EXECUTE FUNCTION hvm_food_private.food_revision();
CREATE FUNCTION hvm_food_private.guard_publication() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF NEW.is_published AND (SELECT enabled FROM public.app_food_configuration WHERE id) THEN
  PERFORM pg_advisory_xact_lock_shared(76,hashtext('food-rules'));
  IF NEW.food_hold OR NEW.food_family IS NULL OR NEW.food_process IS NULL OR
    ROW(NEW.category_id,NEW.title,NEW.description,NEW.packaging_type,NEW.net_weight_grams,NEW.unit_type,NEW.shelf_life_days,NEW.conservation_notes,NEW.food_family,NEW.food_process)
    IS DISTINCT FROM ROW(OLD.category_id,OLD.title,OLD.description,OLD.packaging_type,OLD.net_weight_grams,OLD.unit_type,OLD.shelf_life_days,OLD.conservation_notes,OLD.food_family,OLD.food_process)
  THEN RAISE EXCEPTION 'PRODUCT_FOOD_CHECKLIST_REQUIRED' USING ERRCODE='23514'; END IF;
  IF NOT hvm_food_private.product_is_compliant(NEW.id) THEN RAISE EXCEPTION 'PRODUCT_FOOD_CHECKLIST_REQUIRED' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_food_publication BEFORE UPDATE OF is_published ON public.app_products FOR EACH ROW EXECUTE FUNCTION hvm_food_private.guard_publication();
CREATE FUNCTION hvm_food_private.guard_core_rule() RETURNS trigger LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
BEGIN
 IF OLD.is_core AND (NOT NEW.is_core OR NEW.status='archived' OR NEW.current_version_id IS NULL) THEN
  RAISE EXCEPTION 'FOOD_BASE_RULE_REQUIRED' USING ERRCODE='23514';
 END IF;
 IF NEW.is_core AND (NEW.draft_body->>'scope'<>'national' OR jsonb_array_length(NEW.draft_body->'families')<>0
   OR jsonb_array_length(NEW.draft_body->'processes')<>0 OR jsonb_array_length(NEW.draft_body->'categoryIds')<>0) THEN
  RAISE EXCEPTION 'FOOD_BASE_RULE_REQUIRED' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER trg_food_core_rule BEFORE UPDATE ON public.app_food_rules FOR EACH ROW EXECUTE FUNCTION hvm_food_private.guard_core_rule();
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA hvm_food_private FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA hvm_food_private TO service_role;
GRANT EXECUTE ON FUNCTION hvm_food_private.product_is_compliant(uuid) TO anon,authenticated;
ALTER POLICY products_public_read ON public.app_products USING (is_published AND hvm_store_private.store_is_visible(store_id)
 AND category_id IN (SELECT id FROM public.app_categories WHERE is_active) AND hvm_food_private.product_is_compliant(id));
ALTER POLICY media_public_read ON public.app_product_media USING (product_id IN (SELECT id FROM public.app_products WHERE is_published
 AND hvm_store_private.store_is_visible(store_id) AND category_id IN (SELECT id FROM public.app_categories WHERE is_active)
 AND hvm_food_private.product_is_compliant(id)));
ALTER POLICY price_public_read ON public.app_price_versions USING (product_id IN (SELECT id FROM public.app_products WHERE is_published
 AND hvm_store_private.store_is_visible(store_id) AND category_id IN (SELECT id FROM public.app_categories WHERE is_active)
 AND hvm_food_private.product_is_compliant(id)));
