-- Official federal references and approachable educational starting content.
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('cuidados-gerais','{"title":"Cuidados que acompanham todo alimento","summary":"Comece pelo essencial. Estes cuidados combinam deveres legais e orientações de segurança; a aplicação técnica depende do alimento e da atividade. Confirme exigências adicionais na vigilância sanitária de seu estado e município.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"hygiene","title":"Ambiente, mãos e utensílios limpos","explanation":"Mantenho higiene pessoal, utensílios, instalações e procedimentos adequados à atividade. Evito contato entre alimentos limpos, matérias-primas contaminadas, produtos químicos e pragas.","illustration":"wash"},{"key":"water","title":"Água própria para o uso no alimento","explanation":"Uso água potável quando exigida para lavagem, preparo e contato com o alimento. Mantenho os controles da água e do reservatório de acordo com a origem do abastecimento e as exigências locais.","illustration":"water"},{"key":"preservation","title":"Conservação e validade definidas para este produto","explanation":"O prazo e as condições de conservação informados têm fundamento no alimento, processo, embalagem e controles adotados. Mantenho essas condições durante armazenagem e transporte sob minha responsabilidade; não uso um prazo genérico como se fosse imposto pela lei.","illustration":"cold"},{"key":"information","title":"Embalagem e informações corretas","explanation":"Uso embalagem apropriada ao contato com o alimento. Informo origem, quantidade, conservação e validade; verifico ingredientes, alergênicos, glúten, lote e informações nutricionais quando aplicáveis, inclusive as exceções legais.","illustration":"label"},{"key":"traceability","title":"Origem e rastreabilidade disponíveis","explanation":"Consigo identificar a origem e os lotes, guardar os registros pertinentes e localizar os produtos vendidos. Se houver risco, interromperei a oferta, atenderei o consumidor e colaborarei com o recolhimento e as comunicações exigidas.","illustration":"trace"},{"key":"regularization","title":"Exigências da minha atividade e localidade","explanation":"Verifiquei a regularização exigível para meu estabelecimento e produto junto à autoridade competente: vigilância sanitária, MAPA ou serviço de inspeção, conforme o caso. Dispensas e procedimentos simplificados precisam ser confirmados; este checklist não concede licença.","illustration":"license"},{"key":"environment","title":"Resíduos e embalagens com destino adequado","explanation":"Dou destino adequado aos resíduos e embalagens de acordo com as obrigações aplicáveis à minha atividade. Não descarto contaminantes em solo, cursos de água ou áreas impróprias.","illustration":"environment"}],"sources":[{"title":"Boas práticas: Portaria SVS/MS 326/1997 e RDC 275/2002","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Água: Portaria GM/MS 888/2021 e alterações","url":"https://www.gov.br/saude/pt-br/composicao/svsa/saude-ambiental/vigiagua/legislacao","authority":"Ministério da Saúde","reviewedAt":"2026-10-13"},{"title":"Rotulagem geral: RDC 727/2022; nutricional: RDC 429/2020 e IN 75/2020","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Regularização: RDC 843/2024 e IN 281/2024","url":"https://www.gov.br/anvisa/pt-br/setorregulado/regularizacao/alimentos/dispensa-de-registro/","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Inclusão produtiva: RDC 49/2013","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Recolhimento: RDC 655/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2022/rdc-655-2022","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Código de Defesa do Consumidor: Lei 8.078/1990","url":"https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Comércio eletrônico: Decreto 7.962/2013","url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/decreto/d7962.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Resíduos: Lei 12.305/2010","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12305.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Responsabilidade ambiental: Lei 9.605/1998","url":"https://www.planalto.gov.br/ccivil_03/leis/l9605.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Embalagens: RDC 91/2001 e normas por material","url":"https://www.gov.br/anvisa/pt-br/setorregulado/regularizacao/alimentos/embalagens","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Ao receber, confira embalagem, identificação, validade e condições de conservação. Siga as instruções do produtor, registre problemas e procure atendimento se houver risco à saúde. A declaração do produtor não é certificação sanitária oficial.","producerTerms":""}'::jsonb,'published',true) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Cuidados que acompanham todo alimento","summary":"Comece pelo essencial. Estes cuidados combinam deveres legais e orientações de segurança; a aplicação técnica depende do alimento e da atividade. Confirme exigências adicionais na vigilância sanitária de seu estado e município.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"hygiene","title":"Ambiente, mãos e utensílios limpos","explanation":"Mantenho higiene pessoal, utensílios, instalações e procedimentos adequados à atividade. Evito contato entre alimentos limpos, matérias-primas contaminadas, produtos químicos e pragas.","illustration":"wash"},{"key":"water","title":"Água própria para o uso no alimento","explanation":"Uso água potável quando exigida para lavagem, preparo e contato com o alimento. Mantenho os controles da água e do reservatório de acordo com a origem do abastecimento e as exigências locais.","illustration":"water"},{"key":"preservation","title":"Conservação e validade definidas para este produto","explanation":"O prazo e as condições de conservação informados têm fundamento no alimento, processo, embalagem e controles adotados. Mantenho essas condições durante armazenagem e transporte sob minha responsabilidade; não uso um prazo genérico como se fosse imposto pela lei.","illustration":"cold"},{"key":"information","title":"Embalagem e informações corretas","explanation":"Uso embalagem apropriada ao contato com o alimento. Informo origem, quantidade, conservação e validade; verifico ingredientes, alergênicos, glúten, lote e informações nutricionais quando aplicáveis, inclusive as exceções legais.","illustration":"label"},{"key":"traceability","title":"Origem e rastreabilidade disponíveis","explanation":"Consigo identificar a origem e os lotes, guardar os registros pertinentes e localizar os produtos vendidos. Se houver risco, interromperei a oferta, atenderei o consumidor e colaborarei com o recolhimento e as comunicações exigidas.","illustration":"trace"},{"key":"regularization","title":"Exigências da minha atividade e localidade","explanation":"Verifiquei a regularização exigível para meu estabelecimento e produto junto à autoridade competente: vigilância sanitária, MAPA ou serviço de inspeção, conforme o caso. Dispensas e procedimentos simplificados precisam ser confirmados; este checklist não concede licença.","illustration":"license"},{"key":"environment","title":"Resíduos e embalagens com destino adequado","explanation":"Dou destino adequado aos resíduos e embalagens de acordo com as obrigações aplicáveis à minha atividade. Não descarto contaminantes em solo, cursos de água ou áreas impróprias.","illustration":"environment"}],"sources":[{"title":"Boas práticas: Portaria SVS/MS 326/1997 e RDC 275/2002","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Água: Portaria GM/MS 888/2021 e alterações","url":"https://www.gov.br/saude/pt-br/composicao/svsa/saude-ambiental/vigiagua/legislacao","authority":"Ministério da Saúde","reviewedAt":"2026-10-13"},{"title":"Rotulagem geral: RDC 727/2022; nutricional: RDC 429/2020 e IN 75/2020","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Regularização: RDC 843/2024 e IN 281/2024","url":"https://www.gov.br/anvisa/pt-br/setorregulado/regularizacao/alimentos/dispensa-de-registro/","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Inclusão produtiva: RDC 49/2013","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Recolhimento: RDC 655/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/noticias-anvisa/2022/rdc-655-2022","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Código de Defesa do Consumidor: Lei 8.078/1990","url":"https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Comércio eletrônico: Decreto 7.962/2013","url":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/decreto/d7962.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Resíduos: Lei 12.305/2010","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12305.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Responsabilidade ambiental: Lei 9.605/1998","url":"https://www.planalto.gov.br/ccivil_03/leis/l9605.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Embalagens: RDC 91/2001 e normas por material","url":"https://www.gov.br/anvisa/pt-br/setorregulado/regularizacao/alimentos/embalagens","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Ao receber, confira embalagem, identificação, validade e condições de conservação. Siga as instruções do produtor, registre problemas e procure atendimento se houver risco à saúde. A declaração do produtor não é certificação sanitária oficial.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('vegetais','{"title":"Frutas, folhas, legumes e ervas frescas","summary":"Cuidados com produtos vegetais e com sua origem, incluindo os minimamente processados.","scope":"national","state":null,"municipality":null,"families":["fruits","leafy","vegetables","herbs","mixes"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"plant_origin","title":"Origem e uso seguro de insumos","explanation":"Mantenho a identificação da origem e os registros exigíveis da cadeia de vegetais frescos. Respeito as condições de uso de insumos agrícolas e os limites aplicáveis de resíduos e contaminantes.","illustration":"trace"}],"sources":[{"title":"Rastreabilidade: INC Anvisa/MAPA 2/2018, alterada pela INC 1/2019","url":"https://www.gov.br/agricultura/pt-br/assuntos/camaras-setoriais-tematicas/documentos/camaras-setoriais/hortalicas/2019/56deg-ro-hortalicas/inc-02-2018-e-01-2019-rastreabilidade.pdf","authority":"Anvisa / MAPA","reviewedAt":"2026-10-13"},{"title":"Produtos de frutas e vegetais: RDC 726/2022, quando aplicável","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Contaminantes: RDC 722/2022 e IN 160/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Agrotóxicos: Lei 14.785/2023","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14785.htm","authority":"Planalto","reviewedAt":"2026-10-13"}],"consumerGuidance":"Produtos in natura podem exigir lavagem ou preparo antes do consumo. Confira a informação sobre higienização e mantenha o alimento nas condições indicadas.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Frutas, folhas, legumes e ervas frescas","summary":"Cuidados com produtos vegetais e com sua origem, incluindo os minimamente processados.","scope":"national","state":null,"municipality":null,"families":["fruits","leafy","vegetables","herbs","mixes"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"plant_origin","title":"Origem e uso seguro de insumos","explanation":"Mantenho a identificação da origem e os registros exigíveis da cadeia de vegetais frescos. Respeito as condições de uso de insumos agrícolas e os limites aplicáveis de resíduos e contaminantes.","illustration":"trace"}],"sources":[{"title":"Rastreabilidade: INC Anvisa/MAPA 2/2018, alterada pela INC 1/2019","url":"https://www.gov.br/agricultura/pt-br/assuntos/camaras-setoriais-tematicas/documentos/camaras-setoriais/hortalicas/2019/56deg-ro-hortalicas/inc-02-2018-e-01-2019-rastreabilidade.pdf","authority":"Anvisa / MAPA","reviewedAt":"2026-10-13"},{"title":"Produtos de frutas e vegetais: RDC 726/2022, quando aplicável","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Contaminantes: RDC 722/2022 e IN 160/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Agrotóxicos: Lei 14.785/2023","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14785.htm","authority":"Planalto","reviewedAt":"2026-10-13"}],"consumerGuidance":"Produtos in natura podem exigir lavagem ou preparo antes do consumo. Confira a informação sobre higienização e mantenha o alimento nas condições indicadas.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('minimamente-processados','{"title":"Alimentos lavados, cortados e prontos para preparar","summary":"O corte e a manipulação exigem atenção à contaminação, conservação e validação do prazo de vida útil.","scope":"national","state":null,"municipality":null,"families":[],"processes":["washed_cut","frozen","prepared"],"categoryIds":[],"matchMode":"all","checklist":[{"key":"sanitizing","title":"Higienização adequada ao alimento","explanation":"Sigo um procedimento apropriado ao alimento, com produto autorizado para essa finalidade quando necessário. Respeito concentração, tempo de contato e necessidade de enxágue indicados pelo fabricante e pelo responsável técnico, sem misturar produtos químicos.","illustration":"wash"},{"key":"microbiology","title":"Processo e prazo de validade controlados","explanation":"Avalio os riscos do alimento e adoto os controles microbiológicos aplicáveis, incluindo análises quando exigíveis. Conservação e validade são definidas conforme o produto e sua forma de consumo, não por uma temperatura ou duração universal.","illustration":"cold"}],"sources":[{"title":"Padrões microbiológicos: RDC 724/2022 e IN 161/2022, com alterações","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Boas práticas e procedimentos: RDC 275/2002 e Portaria 326/1997","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"A expressão higienizado não dispensa conferir as instruções de uso. Consuma dentro da validade e respeite a conservação informada, inclusive após abrir a embalagem.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Alimentos lavados, cortados e prontos para preparar","summary":"O corte e a manipulação exigem atenção à contaminação, conservação e validação do prazo de vida útil.","scope":"national","state":null,"municipality":null,"families":[],"processes":["washed_cut","frozen","prepared"],"categoryIds":[],"matchMode":"all","checklist":[{"key":"sanitizing","title":"Higienização adequada ao alimento","explanation":"Sigo um procedimento apropriado ao alimento, com produto autorizado para essa finalidade quando necessário. Respeito concentração, tempo de contato e necessidade de enxágue indicados pelo fabricante e pelo responsável técnico, sem misturar produtos químicos.","illustration":"wash"},{"key":"microbiology","title":"Processo e prazo de validade controlados","explanation":"Avalio os riscos do alimento e adoto os controles microbiológicos aplicáveis, incluindo análises quando exigíveis. Conservação e validade são definidas conforme o produto e sua forma de consumo, não por uma temperatura ou duração universal.","illustration":"cold"}],"sources":[{"title":"Padrões microbiológicos: RDC 724/2022 e IN 161/2022, com alterações","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Boas práticas e procedimentos: RDC 275/2002 e Portaria 326/1997","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"A expressão higienizado não dispensa conferir as instruções de uso. Consuma dentro da validade e respeite a conservação informada, inclusive após abrir a embalagem.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('sucos-polpas','{"title":"Sucos e polpas de frutas","summary":"Sucos e polpas têm enquadramento próprio no MAPA. Verifique estabelecimento, produto, identidade, composição e formas de regularização admitidas.","scope":"national","state":null,"municipality":null,"families":["juices_pulps"],"processes":["pressed_pulped"],"categoryIds":[],"matchMode":"any","checklist":[{"key":"beverage_registration","title":"Enquadramento e regularização de suco ou polpa","explanation":"Verifiquei as exigências do MAPA e os padrões de identidade e qualidade específicos da bebida. Se utilizo o regime de produção artesanal familiar, confirmei seus critérios e obrigações; não presumo dispensa de registro por produzir em pequena escala.","illustration":"license"}],"sources":[{"title":"Bebidas e produtos vegetais: Decreto 12.709/2025","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12709.htm","authority":"Planalto / MAPA","reviewedAt":"2026-10-13"},{"title":"Bebidas: Lei 8.918/1994","url":"https://www.planalto.gov.br/ccivil_03/leis/l8918.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Sucos e polpas artesanais: Lei 13.648/2018 e Decreto 10.026/2019","url":"https://www.gov.br/agricultura/pt-br/assuntos/inspecao/produtos-vegetal/legislacao-programas-nacionais-e-seguranca-dos-alimentos-1/legislacao/bebidas","authority":"MAPA","reviewedAt":"2026-10-13"}],"consumerGuidance":"Observe se é suco, polpa ou outra bebida, os ingredientes e a necessidade de refrigeração ou congelamento. Siga as orientações depois da abertura ou descongelamento.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Sucos e polpas de frutas","summary":"Sucos e polpas têm enquadramento próprio no MAPA. Verifique estabelecimento, produto, identidade, composição e formas de regularização admitidas.","scope":"national","state":null,"municipality":null,"families":["juices_pulps"],"processes":["pressed_pulped"],"categoryIds":[],"matchMode":"any","checklist":[{"key":"beverage_registration","title":"Enquadramento e regularização de suco ou polpa","explanation":"Verifiquei as exigências do MAPA e os padrões de identidade e qualidade específicos da bebida. Se utilizo o regime de produção artesanal familiar, confirmei seus critérios e obrigações; não presumo dispensa de registro por produzir em pequena escala.","illustration":"license"}],"sources":[{"title":"Bebidas e produtos vegetais: Decreto 12.709/2025","url":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2025/decreto/d12709.htm","authority":"Planalto / MAPA","reviewedAt":"2026-10-13"},{"title":"Bebidas: Lei 8.918/1994","url":"https://www.planalto.gov.br/ccivil_03/leis/l8918.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"Sucos e polpas artesanais: Lei 13.648/2018 e Decreto 10.026/2019","url":"https://www.gov.br/agricultura/pt-br/assuntos/inspecao/produtos-vegetal/legislacao-programas-nacionais-e-seguranca-dos-alimentos-1/legislacao/bebidas","authority":"MAPA","reviewedAt":"2026-10-13"}],"consumerGuidance":"Observe se é suco, polpa ou outra bebida, os ingredientes e a necessidade de refrigeração ou congelamento. Siga as orientações depois da abertura ou descongelamento.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('ervas-chas','{"title":"Ervas, especiarias e chás","summary":"A espécie e a parte vegetal usadas como alimento precisam ser adequadas e autorizadas ao uso pretendido.","scope":"national","state":null,"municipality":null,"families":["herbs"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"edible_species","title":"Espécie e parte vegetal apropriadas","explanation":"Identifico corretamente as espécies e utilizo somente partes adequadas ou autorizadas para a finalidade alimentar. Verifico os requisitos para chás, especiarias e temperos; não anuncio efeitos medicinais não autorizados.","illustration":"label"}],"sources":[{"title":"Chás, especiarias e temperos: RDC 716/2022 e IN 159/2022, com alterações","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Confira a espécie, os ingredientes e o modo de preparo. Alegações de tratamento de doenças não devem ser presumidas para alimentos.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Ervas, especiarias e chás","summary":"A espécie e a parte vegetal usadas como alimento precisam ser adequadas e autorizadas ao uso pretendido.","scope":"national","state":null,"municipality":null,"families":["herbs"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"edible_species","title":"Espécie e parte vegetal apropriadas","explanation":"Identifico corretamente as espécies e utilizo somente partes adequadas ou autorizadas para a finalidade alimentar. Verifico os requisitos para chás, especiarias e temperos; não anuncio efeitos medicinais não autorizados.","illustration":"label"}],"sources":[{"title":"Chás, especiarias e temperos: RDC 716/2022 e IN 159/2022, com alterações","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Confira a espécie, os ingredientes e o modo de preparo. Alegações de tratamento de doenças não devem ser presumidas para alimentos.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('graos-castanhas','{"title":"Grãos, cereais, farinhas, sementes e castanhas","summary":"Armazenamento, umidade e contaminação merecem cuidados próprios nesses alimentos.","scope":"national","state":null,"municipality":null,"families":["grains","nuts"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"dry_storage","title":"Armazenamento e informação de alergênicos","explanation":"Controlo umidade, pragas e deterioração de acordo com o alimento. Verifico padrões de contaminantes e microbiologia e as declarações aplicáveis de alergênicos e glúten.","illustration":"label"}],"sources":[{"title":"Cereais e farinhas: RDC 711/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Contaminantes: RDC 722/2022 e IN 160/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Rotulagem e alergênicos: RDC 727/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Glúten: Lei 10.674/2003","url":"https://www.planalto.gov.br/ccivil_03/leis/2003/l10.674.htm","authority":"Planalto","reviewedAt":"2026-10-13"}],"consumerGuidance":"Leia a composição, os avisos de alergênicos e glúten, especialmente quando houver restrições alimentares. Armazene conforme o rótulo.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Grãos, cereais, farinhas, sementes e castanhas","summary":"Armazenamento, umidade e contaminação merecem cuidados próprios nesses alimentos.","scope":"national","state":null,"municipality":null,"families":["grains","nuts"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"dry_storage","title":"Armazenamento e informação de alergênicos","explanation":"Controlo umidade, pragas e deterioração de acordo com o alimento. Verifico padrões de contaminantes e microbiologia e as declarações aplicáveis de alergênicos e glúten.","illustration":"label"}],"sources":[{"title":"Cereais e farinhas: RDC 711/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Contaminantes: RDC 722/2022 e IN 160/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Rotulagem e alergênicos: RDC 727/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Glúten: Lei 10.674/2003","url":"https://www.planalto.gov.br/ccivil_03/leis/2003/l10.674.htm","authority":"Planalto","reviewedAt":"2026-10-13"}],"consumerGuidance":"Leia a composição, os avisos de alergênicos e glúten, especialmente quando houver restrições alimentares. Armazene conforme o rótulo.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('origem-animal','{"title":"Alimentos de origem animal","summary":"Carnes, pescado, ovos, leite, derivados e mel possuem controles próprios. Produção artesanal não equivale a dispensa automática de inspeção.","scope":"national","state":null,"municipality":null,"families":["animal"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"animal_inspection","title":"Inspeção e alcance da comercialização","explanation":"Tenho a inspeção e a regularização exigíveis e respeito o alcance de venda autorizado pelo serviço competente. Verifiquei os requisitos de SIF, SISBI-POA, serviço estadual ou municipal e, se aplicável, dos selos artesanais.","illustration":"license"}],"sources":[{"title":"Inspeção: Lei 1.283/1950","url":"https://www.planalto.gov.br/ccivil_03/leis/l1283.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"RIISPOA: Decreto 9.013/2017 e alterações","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/decreto/d9013.htm","authority":"Planalto / MAPA","reviewedAt":"2026-10-13"}],"consumerGuidance":"Confira identificação e selo de inspeção quando exigíveis, conservação e validade. O checklist da plataforma não substitui o serviço oficial de inspeção.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Alimentos de origem animal","summary":"Carnes, pescado, ovos, leite, derivados e mel possuem controles próprios. Produção artesanal não equivale a dispensa automática de inspeção.","scope":"national","state":null,"municipality":null,"families":["animal"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"animal_inspection","title":"Inspeção e alcance da comercialização","explanation":"Tenho a inspeção e a regularização exigíveis e respeito o alcance de venda autorizado pelo serviço competente. Verifiquei os requisitos de SIF, SISBI-POA, serviço estadual ou municipal e, se aplicável, dos selos artesanais.","illustration":"license"}],"sources":[{"title":"Inspeção: Lei 1.283/1950","url":"https://www.planalto.gov.br/ccivil_03/leis/l1283.htm","authority":"Planalto","reviewedAt":"2026-10-13"},{"title":"RIISPOA: Decreto 9.013/2017 e alterações","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/decreto/d9013.htm","authority":"Planalto / MAPA","reviewedAt":"2026-10-13"}],"consumerGuidance":"Confira identificação e selo de inspeção quando exigíveis, conservação e validade. O checklist da plataforma não substitui o serviço oficial de inspeção.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('preparados','{"title":"Mixes e alimentos preparados","summary":"A combinação de ingredientes pode alterar o enquadramento, a conservação e as informações ao consumidor.","scope":"national","state":null,"municipality":null,"families":["mixes"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"prepared_food","title":"Ingredientes, preparo e enquadramento verificados","explanation":"Informo os ingredientes e riscos aplicáveis e verifiquei o enquadramento da minha atividade. Para serviços de alimentação, observo as boas práticas correspondentes; a RDC 216/2004 não é usada como regra universal para toda indústria.","illustration":"wash"}],"sources":[{"title":"Serviços de alimentação: RDC 216/2004, quando aplicável","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Alimentos prontos: RDC 719/2022, quando aplicável","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Rotulagem: RDC 727/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Verifique ingredientes, alergênicos, conservação e instruções antes do consumo. Receitas diferentes podem exigir cuidados diferentes.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Mixes e alimentos preparados","summary":"A combinação de ingredientes pode alterar o enquadramento, a conservação e as informações ao consumidor.","scope":"national","state":null,"municipality":null,"families":["mixes"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"prepared_food","title":"Ingredientes, preparo e enquadramento verificados","explanation":"Informo os ingredientes e riscos aplicáveis e verifiquei o enquadramento da minha atividade. Para serviços de alimentação, observo as boas práticas correspondentes; a RDC 216/2004 não é usada como regra universal para toda indústria.","illustration":"wash"}],"sources":[{"title":"Serviços de alimentação: RDC 216/2004, quando aplicável","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Alimentos prontos: RDC 719/2022, quando aplicável","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"},{"title":"Rotulagem: RDC 727/2022","url":"https://www.gov.br/anvisa/pt-br/assuntos/alimentos/legislacao","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Verifique ingredientes, alergênicos, conservação e instruções antes do consumo. Receitas diferentes podem exigir cuidados diferentes.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
DO $$ DECLARE rid uuid; vid uuid; BEGIN INSERT INTO public.app_food_rules(slug,draft_body,status,is_core) VALUES ('outros-alimentos','{"title":"Verificação do enquadramento do alimento","summary":"Quando o produto não se enquadra nas famílias disponíveis, é necessário confirmar os requisitos próprios antes de anunciar.","scope":"national","state":null,"municipality":null,"families":["other"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"specific_framework","title":"Exigências específicas confirmadas","explanation":"Confirmei o enquadramento deste alimento e as normas específicas com a autoridade competente ou profissional habilitado. Novos ingredientes, alegações especiais e categorias de maior risco podem exigir avaliações e regularização próprias.","illustration":"license"}],"sources":[{"title":"Regularização e categorias: RDC 843/2024 e IN 281/2024","url":"https://www.gov.br/anvisa/pt-br/setorregulado/regularizacao/alimentos/dispensa-de-registro/","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Confira a descrição, composição e os cuidados próprios do produto. A classificação como outros não dispensa as exigências específicas.","producerTerms":""}'::jsonb,'published',false) RETURNING id INTO rid; INSERT INTO public.app_food_rule_versions(rule_id,version,body) VALUES(rid,1,'{"title":"Verificação do enquadramento do alimento","summary":"Quando o produto não se enquadra nas famílias disponíveis, é necessário confirmar os requisitos próprios antes de anunciar.","scope":"national","state":null,"municipality":null,"families":["other"],"processes":[],"categoryIds":[],"matchMode":"all","checklist":[{"key":"specific_framework","title":"Exigências específicas confirmadas","explanation":"Confirmei o enquadramento deste alimento e as normas específicas com a autoridade competente ou profissional habilitado. Novos ingredientes, alegações especiais e categorias de maior risco podem exigir avaliações e regularização próprias.","illustration":"license"}],"sources":[{"title":"Regularização e categorias: RDC 843/2024 e IN 281/2024","url":"https://www.gov.br/anvisa/pt-br/setorregulado/regularizacao/alimentos/dispensa-de-registro/","authority":"Anvisa","reviewedAt":"2026-10-13"}],"consumerGuidance":"Confira a descrição, composição e os cuidados próprios do produto. A classificação como outros não dispensa as exigências específicas.","producerTerms":""}'::jsonb) RETURNING id INTO vid; UPDATE public.app_food_rules SET current_version_id=vid WHERE id=rid; END $$;
INSERT INTO public.app_food_materials(body,status) VALUES ('{"title":"Do alimento limpo à embalagem","description":"Separe o que está sujo do que está pronto. Higienize mãos, superfícies e utensílios. Quando usar sanitizante, siga as instruções autorizadas para aquele alimento: não improvise concentrações e não misture produtos.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","kind":"guide","audience":"both","url":null,"assetId":null,"illustration":"wash"}'::jsonb,'published');
INSERT INTO public.app_food_materials(body,status) VALUES ('{"title":"Conservar também é cuidar","description":"Defina conservação e validade com base no seu produto e processo. Controle a temperatura quando exigida, da preparação à entrega. Para o consumidor: siga o rótulo e observe o prazo e os cuidados depois de abrir.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","kind":"guide","audience":"both","url":null,"assetId":null,"illustration":"cold"}'::jsonb,'published');
INSERT INTO public.app_food_materials(body,status) VALUES ('{"title":"Uma etiqueta que explica","description":"Mostre o que está sendo vendido: origem, quantidade, conservação e validade. Verifique lote, ingredientes, alergênicos e tabela nutricional conforme o enquadramento, inclusive as exceções. Não use o aceite do checklist como selo oficial.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","kind":"guide","audience":"both","url":null,"assetId":null,"illustration":"label"}'::jsonb,'published');
INSERT INTO public.app_food_materials(body,status) VALUES ('{"title":"Da origem ao destino","description":"Guarde os registros do alimento e seus lotes. Isso ajuda a encontrar a origem, atender o consumidor e agir rapidamente se houver risco. Os registros do aplicativo apoiam o controle; mantenha também a documentação exigível.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","kind":"guide","audience":"producer","url":null,"assetId":null,"illustration":"trace"}'::jsonb,'published');
INSERT INTO public.app_food_materials(body,status) VALUES ('{"title":"Regularização sem complicar","description":"A vigilância sanitária local pode orientar o enquadramento e os procedimentos simplificados para pequenos empreendimentos. As dispensas dependem da atividade e da norma aplicável. Consulte as fontes e peça orientação antes de iniciar uma atividade nova.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","kind":"link","audience":"producer","url":"https://www.gov.br/anvisa/pt-br/assuntos/snvs/inclusao-produtiva","assetId":null,"illustration":"license"}'::jsonb,'published');
INSERT INTO public.app_food_materials(body,status) VALUES ('{"title":"Orgânico: informe com responsabilidade","description":"Não anuncie como orgânico apenas por não utilizar um insumo. Verifique os requisitos de produção e de comprovação da conformidade, incluindo as condições próprias da venda direta da agricultura familiar, quando aplicáveis.","scope":"national","state":null,"municipality":null,"families":[],"processes":[],"categoryIds":[],"matchMode":"all","kind":"link","audience":"both","url":"https://www.gov.br/agricultura/pt-br/assuntos/sustentabilidade/organicos/legislacao-organicos","assetId":null,"illustration":"environment"}'::jsonb,'published');
